const raw = $json;
const data = raw.body || raw;

if (!data.article_id) {
  throw new Error(
    `article_id가 없습니다. 현재 입력값: ${JSON.stringify(data)}`
  );
}

if (!data.title) {
  throw new Error(
    `기사 title이 없습니다. 현재 입력값: ${JSON.stringify(data)}`
  );
}

if (!data.content) {
  throw new Error(
    `기사 content가 없습니다. 현재 입력값: ${JSON.stringify(data)}`
  );
}

const selectedKeywords =
  Array.isArray(data.selected_keywords)
    ? data.selected_keywords
    : [];

return [
  {
    json: {
      article_id: data.article_id,
      title: data.title,
      content: data.content,
      selected_keywords: selectedKeywords,
      requirements: data.requirements || '',
      platform: 'threads'
    }
  }
];

return items.map(item => {
  const data = item.json;

  return {
    json: {
      ...data,

      platform_rules: {
        output_type: 'threads_post',

        concise: true,

        short_paragraphs: true,

        opening_required: true,

        closing_required: true,

        one_core_message_per_paragraph: true,

        preserve_article_context: true,

        evidence_required: true,

        editable_draft: true,

        image_required: false
      }
    }
  };
});

